import{_ as e,c as i,o as t,a3 as o}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"隐私选择","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy-choices.md","filePath":"zh-CN/guide/privacy-choices.md","lastUpdated":1786595765000}'),s={name:"zh-CN/guide/privacy-choices.md"};function l(r,a,n,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="隐私选择" tabindex="-1">隐私选择 <a class="header-anchor" href="#隐私选择" aria-label="Permalink to &quot;隐私选择&quot;">​</a></h1><p>ClipboardxAI 是一款本地优先的应用。由于你的数据始终留在你的设备上，我们不会收集、出售或共享任何个人信息。</p><h2 id="我们本地保存的数据" tabindex="-1">我们本地保存的数据 <a class="header-anchor" href="#我们本地保存的数据" aria-label="Permalink to &quot;我们本地保存的数据&quot;">​</a></h2><p>ClipboardxAI 将所有数据保存在你的 Mac 本地：</p><ul><li>剪贴板历史与应用偏好</li><li>自定义操作与配置</li><li>API key（保存在 Keychain 中，仅在你配置了云端提供商时）</li><li>调试日志（如已启用）</li></ul><p>这些数据均不会由应用本身上传到任何服务器。</p><h2 id="云端-ai-选择性开启-cloud-ai-opt-in" tabindex="-1">云端 AI 选择性开启（Cloud AI Opt-In） <a class="header-anchor" href="#云端-ai-选择性开启-cloud-ai-opt-in" aria-label="Permalink to &quot;云端 AI 选择性开启（Cloud AI Opt-In）&quot;">​</a></h2><p>云端 AI 功能<strong>默认关闭</strong>。它们仅在你触发某项云端操作时，使用你自己的 API key，将内容发送给你选择的提供商。你可以在 <strong>设置 → AI（Settings → AI）</strong> 中查看或删除已配置的提供商。</p><h2 id="你的权利" tabindex="-1">你的权利 <a class="header-anchor" href="#你的权利" aria-label="Permalink to &quot;你的权利&quot;">​</a></h2><p>由于 ClipboardxAI 不在我们的服务器上收集或存储个人数据，因此我们没有任何可供访问、删除或转移的个人数据。你的所有数据都可以在应用内直接管理，或通过移除应用的容器文件夹来管理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><h2 id="不出售声明-do-not-sell" tabindex="-1">不出售声明（Do Not Sell） <a class="header-anchor" href="#不出售声明-do-not-sell" aria-label="Permalink to &quot;不出售声明（Do Not Sell）&quot;">​</a></h2><p>ClipboardxAI 不出售任何个人信息。我们不使用任何第三方的分析、广告或追踪服务。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>如果你对隐私选择有疑问，请在以下地址提交 issue： <code>https://github.com/clipboardxAI/clipboard-site/issues</code></p>',15)])])}const b=e(s,[["render",l]]);export{u as __pageData,b as default};
